import { Component, Element, Host, Prop, h } from "@stencil/core";
import retargetEvents from "react-shadow-dom-retarget-events";
import { renderChart } from "./RenderChart";

/**
 * @since 0.0.9
 * @status beta
 *
 */
@Component({
	tag: "hbr-sankey",
	styleUrl: "hbr-sankey.scss",
	shadow: true,
})
export class HuiSankey {
	/**
	 * config object for the chart,
	 * refer: https://nivo.rocks/sankey/
	 */
	@Prop() config: any;
	/**
	 * width of the container in CSS length units
	 */
	@Prop() width = "100%";
	/**
	 * height of the container in CSS length units
	 */
	@Prop() height = "300px";

	@Element() private el: HTMLHbrSankeyElement;

	componentDidLoad() {
		this.createChart();
		retargetEvents(this.el.shadowRoot);
	}

	componentShouldUpdate() {
		this.createChart();
		return false;
	}

	createChart() {
		const root = this.el.shadowRoot.querySelector("div");

		renderChart({
			el: root,
			config: { ...this.config },
		});
	}

	render() {
		return (
			<Host>
				<div id="root" style={{ width: this.width, height: this.height }} />
			</Host>
		);
	}
}
