import { ResponsiveSankey as Sankey } from "@harbor-charts/sankey";
import merge from "deepmerge";
import React from "react";
import { createRoot } from "react-dom/client";
//import {getBaseConfig} from "../../utils/baseConfig";
import { combineMergeArray } from "../../../utils/combineMergeArray";

function getSankeyBaseConfig(data) {
	return {
		data,
	};
}

export function renderChart(params: any) {
	const { el, config } = params;
	/**
	 * merges: common charts config < bar charts common config < config from user
	 * TODO: do we need un modifiable config?
	 */
	const _config = merge.all([getSankeyBaseConfig(config.data), config], {
		arrayMerge: combineMergeArray,
	});
	const root = createRoot(el);
	root.render(React.createElement(Sankey, _config, null));
}
